namespace sv_fa6828dca35542b99ba7b3c64f8e0b79.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme != value)
            {
                _theme = value;
                NotifyStateChanged();
            }
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor != value)
            {
                _accentColor = value;
                NotifyStateChanged();
            }
        }
    }

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme: @ThemeService.Theme">
    @GetThemeIcon()
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetThemeIcon() => ThemeService.Theme switch
    {
        Services.ThemeMode.Light => "☀️",
        Services.ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject Services.ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" @bind="SelectedTheme">
        <option value="@Services.ThemeMode.Light">Light</option>
        <option value="@Services.ThemeMode.Dark">Dark</option>
        <option value="@Services.ThemeMode.System">System</option>
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color" @bind="SelectedAccentColor" />
</div>

<p>Current theme: <strong>@ThemeService.Theme</strong></p>
<p>Current accent: <span style="color: @ThemeService.AccentColor;">@ThemeService.AccentColor</span></p>

@code {
    private Services.ThemeMode SelectedTheme
    {
        get => ThemeService.Theme;
        set => ThemeService.Theme = value;
    }

    private string SelectedAccentColor
    {
        get => ThemeService.AccentColor;
        set => ThemeService.AccentColor = value;
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= HandleThemeChanged;
    }
}

